class Solution:
    def handleQuery(self, nums1: List[int], nums2: List[int], queries: List[List[int]]) -> List[int]:
        a = nums1[:]
        total = sum(nums2)
        res = []
        for t, x, y in queries:
            if t == 1:
                for i in range(x, y + 1):
                    a[i] ^= 1
            elif t == 2:
                total += x * sum(a)
            else:
                res.append(total)
        return res

