class Solution {
public:
    vector<long long> handleQuery(vector<int>& nums1, vector<int>& nums2, vector<vector<int>>& queries) {
        vector<int> a = nums1;
        long long total = accumulate(nums2.begin(), nums2.end(), 0LL);
        vector<long long> res;
        for (auto& q : queries) {
            if (q[0] == 1) for (int i = q[1]; i <= q[2]; i++) a[i] ^= 1;
            else if (q[0] == 2) total += (long long)q[1] * accumulate(a.begin(), a.end(), 0LL);
            else res.push_back(total);
        }
        return res;
    }
};

