class Solution {
    public long[] handleQuery(int[] nums1, int[] nums2, int[][] queries) {
        int[] a = nums1.clone();
        long total = 0;
        for (int v : nums2) total += v;
        long[] tmp = new long[queries.length];
        int m = 0;
        for (int[] q : queries) {
            if (q[0] == 1) for (int i = q[1]; i <= q[2]; i++) a[i] ^= 1;
            else if (q[0] == 2) { long s = 0; for (int v : a) s += v; total += (long) q[1] * s; }
            else tmp[m++] = total;
        }
        return Arrays.copyOf(tmp, m);
    }
}

