class Solution:
    def handleQuery(self, nums1: List[int], nums2: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums1)
        cnt = [0] * (4 * n)
        lz = [False] * (4 * n)
        def build(o, l, r):
            if l == r:
                cnt[o] = nums1[l]
                return
            m = (l + r) // 2
            build(2 * o, l, m)
            build(2 * o + 1, m + 1, r)
            cnt[o] = cnt[2 * o] + cnt[2 * o + 1]
        def appl(o, l, r):
            cnt[o] = (r - l + 1) - cnt[o]
            lz[o] = not lz[o]
        def update(o, l, r, a, b):
            if b < l or r < a:
                return
            if a <= l and r <= b:
                appl(o, l, r)
                return
            m = (l + r) // 2
            if lz[o]:
                appl(2 * o, l, m)
                appl(2 * o + 1, m + 1, r)
                lz[o] = False
            update(2 * o, l, m, a, b)
            update(2 * o + 1, m + 1, r, a, b)
            cnt[o] = cnt[2 * o] + cnt[2 * o + 1]
        build(1, 0, n - 1)
        total = sum(nums2)
        res = []
        for t, x, y in queries:
            if t == 1:
                update(1, 0, n - 1, x, y)
            elif t == 2:
                total += x * cnt[1]
            else:
                res.append(total)
        return res

