    vector<bool> lz;
    int n;
    void build(int o, int l, int r, vector<int>& a) {
        if (l == r) { cnt[o] = a[l]; return; }
        int m = (l + r) / 2;
        build(2*o, l, m, a); build(2*o+1, m+1, r, a);
        cnt[o] = cnt[2*o] + cnt[2*o+1];
    }
    void appl(int o, int l, int r) { cnt[o] = (r - l + 1) - cnt[o]; lz[o] = !lz[o]; }
    void update(int o, int l, int r, int ql, int qr) {
        if (qr < l || r < ql) return;
        if (ql <= l && r <= qr) { appl(o, l, r); return; }
        int m = (l + r) / 2;
        if (lz[o]) { appl(2*o, l, m); appl(2*o+1, m+1, r); lz[o] = false; }
        update(2*o, l, m, ql, qr); update(2*o+1, m+1, r, ql, qr);
        cnt[o] = cnt[2*o] + cnt[2*o+1];
    }
public:
    vector<long long> handleQuery(vector<int>& nums1, vector<int>& nums2, vector<vector<int>>& queries) {
        n = nums1.size();
        cnt.assign(4 * n, 0); lz.assign(4 * n, false);
        build(1, 0, n - 1, nums1);
        long long total = accumulate(nums2.begin(), nums2.end(), 0LL);
        vector<long long> res;
        for (auto& q : queries) {
            if (q[0] == 1) update(1, 0, n - 1, q[1], q[2]);
            else if (q[0] == 2) total += (long long)q[1] * cnt[1];
            else res.push_back(total);
        }
        return res;
    }
};

